const storageSummary=(()=>{const capacity=2*1024**4,files=initialItems.filter(item=>item.itemType==='file'),sum=list=>list.reduce((total,item)=>total+bytesFromSize(item.size),0),format=value=>value>=1024**3?`${(value/1024**3).toFixed(1)}GB`:value>=1024**2?`${(value/1024**2).toFixed(1)}MB`:`${Math.round(value/1024)}KB`,isRecycle=item=>item.parentId==='recycle-bin',isInvalid=item=>!isRecycle(item)&&item.source==='backup',isLarge=item=>!isRecycle(item)&&!isInvalid(item)&&bytesFromSize(item.size)>=50*1024**3,used=sum(files),recycle=sum(files.filter(isRecycle)),invalid=sum(files.filter(isInvalid)),large=sum(files.filter(isLarge)),normal=sum(files.filter(item=>!isRecycle(item)&&!isInvalid(item)&&!isLarge(item))),percent=value=>`${(value/capacity*100).toFixed(5)}%`,tip=(type,value)=>`类型：${type}&#10;大小：${format(value)}&#10;占比：${(value/capacity*100).toFixed(1)}%`;return{used,usedLabel:format(used),values:{recycle:format(recycle),invalid:format(invalid),large:format(large),normal:format(normal)},segments:{recycle:percent(recycle),invalid:percent(invalid),large:percent(large),other:percent(normal)},tips:{recycle:tip('回收站文件',recycle),invalid:tip('失效文件',invalid),large:tip('超大文件',large),other:tip('正常文件',normal)}}})();

