function RecentPlaybackMaterial(){useEffect(()=>{const recent=document.querySelector('.recent'),card=document.querySelector('.cards article:first-child');if(!recent||!card)return;let videos=initialItems.filter(item=>item.category==='video'&&item.itemType==='file').slice(0,4).map((item,index)=>({...item,playedPercent:[64,39,50,61][index]}));const render=()=>{recent.innerHTML=videos.map((item,index)=>{const cover=item.cover||`/assets/thumb${index%2+1}.webp`,duration=['02:24:00','01:36:18','08:45:12','00:48:36'][index]||'00:00:00';return `<div class="recent-video-card"><div class="poster movie"><img class="recent-video-material" src="${cover}" alt="视频封面"/><b>已看${Math.round(item.playedPercent||0)}%</b><i>${duration}</i></div><div><p>${item.name}</p><small><img class="client-icon" src="/assets/client.webp" alt="客户端"/>客户端　刚刚</small></div></div>`}).join('');recent.querySelectorAll('.recent-video-material').forEach(image=>{const sync=()=>image.parentElement.classList.toggle('is-portrait',image.naturalHeight>image.naturalWidth);image.addEventListener('load',sync,{once:true});if(image.complete)sync()})};const update=e=>{const item=e.detail;if(!item||item.category!=='video')return;videos=[{...item,playedPercent:item.playedPercent||0},...videos.filter(video=>video.id!==item.id)].slice(0,4);render()},progress=e=>{const{ id,playedPercent }=e.detail||{};const index=videos.findIndex(video=>video.id===id);if(index<0)return;videos[index]={...videos[index],playedPercent};render()},reset=()=>{videos=[];render()},observer=new MutationObserver(()=>{if(card.classList.contains('is-video-playback-empty'))reset()});render();observer.observe(card,{attributes:true,attributeFilter:['class']});window.addEventListener('drive-recent-playback',update);window.addEventListener('drive-recent-playback-progress',progress);return()=>{window.removeEventListener('drive-recent-playback',update);window.removeEventListener('drive-recent-playback-progress',progress);observer.disconnect()}},[]);return null}
function RecentNewMaterial(){useEffect(()=>{const root=document.querySelector('.cards article:nth-child(2) .new');if(!root)return;const current=[{id:'recent-brief',name:'项目需求说明.docx',category:'document',kind:'word',size:'2.4MB',modifiedAt:'2026.09.24 10:20'},{id:'recent-budget',name:'2026 年度预算.xlsx',category:'document',kind:'excel',size:'4.8MB',modifiedAt:'2026.09.24 09:36'},{id:'recent-review',name:'产品方案评审.pptx',category:'document',kind:'ppt',size:'8.3MB',modifiedAt:'2026.09.23 18:08'},{id:'recent-guide',name:'使用手册.pdf',category:'document',kind:'pdf',size:'12.6MB',modifiedAt:'2026.09.23 15:40'},{id:'recent-operation',name:'季度运营数据汇总.xlsx',category:'document',kind:'excel',size:'4.8MB',modifiedAt:'2026.09.23 12:44'},{id:'recent-requirement',name:'产品需求说明书.pdf',category:'document',kind:'pdf',size:'12.6MB',modifiedAt:'2026.09.22 18:30'}],render=items=>{const material=item=>`/assets/type-${item.kind||'word'}.webp`,gap=parseFloat(getComputedStyle(root).columnGap)||20,itemWidth=80,capacity=Math.max(1,Math.floor((root.clientWidth+gap)/(itemWidth+gap)));root.innerHTML=items.slice(0,capacity).map(item=>`<div class="new-item"><img class="new-material" src="${material(item)}" alt=""/><span class="new-name">${item.name}</span><span class="item-tooltip recent-new-tooltip" role="tooltip"><span>名称：${item.name}</span><span>大小：${item.size}</span><span>修改时间：${item.modifiedAt}</span></span></div>`).join('')},resize=new ResizeObserver(()=>render(current));render(current);resize.observe(root);return()=>resize.disconnect()},[]);return null}
